// T4 spike probe plugin (generated by spike/probe-alias-reach.ts).
// Registers alias-named tools; every execute writes a marker JSONL line;
// tool.execute.before records every invoked tool name opencode sees.
import { appendFileSync, mkdirSync } from "node:fs"
import { join } from "node:path"
import { tool } from "@opencode-ai/plugin"
import type { Plugin } from "@opencode-ai/plugin"

const MARKER_DIR = "/tmp/opencode-qa-b0/markers"

function record(kind: string, name: string, extra: Record<string, unknown>): void {
  mkdirSync(MARKER_DIR, { recursive: true })
  const entry = JSON.stringify({ kind, name, ts: new Date().toISOString(), ...extra })
  appendFileSync(join(MARKER_DIR, kind + ".jsonl"), entry + "\n")
}

function probeTool(name: string) {
  return tool({
    description: "T4 spike probe alias tool " + name + ". Always callable; writes a marker file.",
    args: { input: tool.schema.string().optional() },
    execute: async (args, context) => {
      record("execute", name, { args: args, sessionID: context.sessionID })
      return { title: "probe-" + name, output: "probe tool " + name + " executed; marker written", metadata: { probe: true } }
    },
  })
}

const ProbeAliasPlugin: Plugin = async () => ({
  "tool.execute.before": async (input, output) => {
    record("before", input.tool, { callID: input.callID, args: output.args })
  },
  tool: {
    Task_Create: probeTool("Task_Create"),
    TodoWrite: probeTool("TodoWrite"),
    Agent: probeTool("Agent"),
  },
})

export default ProbeAliasPlugin
